/bin/bash -lc "python - <<'PY'
from pathlib import Path
import csv,re
met_pat=re.compile(r'(metabol|biosynthetic|catabolic|cholesterol|sterol|retinoid|lipid|alcohol|fatty acid|carbohydrate|amino acid|glycolysis|oxidative|respiratory|energy|nucleotide|mitochond)',re.I)
for p in sorted(Path('/workspace').glob('go_*_results.tabular')):
    sig=[]; met=[]
    with p.open(newline='') as fh:
        for row in csv.DictReader(fh,delimiter='\\t'):
            if float(row['adjusted_p_value'])<0.05:
                sig.append(row)
                if met_pat.search(row['term']): met.append(row)
    print(p.stem, 'sig',len(sig),'met_like',len(met))
    for row in met[:12]: print(' ',row['adjusted_p_value'],row['term'])
PY"

